window.RP_SESSION={"id":"S-7aad56c536b1","messages":[{"id":"RP-0172036","time":"2026-06-09T13:09:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"어윽, 배야...\"\n\n엉거주춤한 자세로 배를 잡은 채, 화장실로 향하는 티아멧. 뭔가 잘못 먹은 듯 하네요.","characters":["P-22fdf8486544"]},{"id":"RP-0172037","time":"2026-06-09T13:43:00+09:00","room":"RP","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 잠깐! 지금 아파할 시간이 없어! \"\n\n정말 오랜만에 술에 쩔어있지 않은 잭은 들뜬 표정으로 달려와 티아멧을 막아섭니다.\n\n\" 누가 신입을 탈출해서 정식 길드원이 됐는지 알아? \"","characters":["P-58df75b248fb"]},{"id":"RP-0172038","time":"2026-06-09T14:19:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"아, 아니... 안 궁금해!!\"\n\n다급하게 잭을 밀쳐냅니다.","characters":["P-22fdf8486544"]},{"id":"RP-0172039","time":"2026-06-09T14:42:00+09:00","room":"RP","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 악! \"\n\n잭이 밀쳐지며 바닥에 넘어집니다.\n그는 그대로 굉장히 서운한 표정을 하고 티아멧을 지켜봅니다.\n\n\" 내가... 내가 됐어... \"","characters":["P-58df75b248fb"]},{"id":"RP-0172040","time":"2026-06-09T14:47:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"귀에 들어오는 게 없는 티아멧은 비틀비틀 걸어갑니다.\n\n\"으윽...\"","characters":["P-22fdf8486544"]},{"id":"RP-0172041","time":"2026-06-09T16:15:00+09:00","room":"RP","name":"잭 해리슨","profile":"잭 해리슨","identity":"reviewed","type":"dialogue","body":"\" 난 그냥 짧은 축하를 원한거야. 요즘 사람들은 정도 없네. \"\n\n잭은 비틀거리며 사라지는 티아멧의 뒷모습을 보며 중얼거립니다.\n\n\" 이건 위로주. \"\n\n그러고는 찬장에서 귀신같이 가격대가 있는 술을 찾아내서 코르크를 땁니다.","characters":["P-58df75b248fb"]},{"id":"RP-0172042","time":"2026-06-10T10:49:00+09:00","room":"RP","name":"티아멧","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-22fdf8486544"]},{"id":"RP-0172043","time":"2026-06-10T10:49:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
